using the Narwhal router.","poolAmountOut":"Amount of pool tokens that must be received to not revert."}},"swapExactETHForTokensAndMint(bytes32[],address,uint256)":{"details":"Swaps ether for each token in `path` using their Uniswap pairs, then mints at least `minPoolAmountOut` pool tokens from `indexPool`.","params":{"indexPool":"Address of the index pool to mint tokens from.","minPoolAmountOut":"Amount of pool tokens that must be received to not revert.","path":"Array of encoded tokens to swap using the Narwhal router."}},"swapExactTokensForTokensAndMint(uint256,bytes32[],address,uint256)":{"details":"Swaps a token for each other token in `path` using their Uniswap pairs, then mints at least `minPoolAmountOut` pool tokens from `indexPool`.","params":{"amountIn":"Amount of the first token in `path` to swap.","indexPool":"Address of the index pool to mint tokens from.","minPoolAmountOut":"Amount of pool tokens that must be received to not revert.","path":"Array of encoded tokens to swap using the Narwhal router."}},"swapTokensForAllTokensAndMintExact(address,bytes32[],uint256,address,uint256)":{"details":"Swaps an input token for every underlying token in an index pool, then mints `poolAmountOut` pool tokens from the pool. Up to one intermediary token may be provided in `intermediaries` for each underlying token in the index pool. If a null address is provided as an intermediary, the input token will be swapped directly for the output token. `intermediaries` is an encoded Narwhal path with a one-byte prefix indicating whether the first swap should use sushiswap.","params":{"amountInMax":"Maximumm amount of `tokenIn` to spend.","indexPool":"Address of the index pool to mint tokens with.","intermediaries":"Encoded Narwhal tokens array with a one-byte prefix indicating whether the swap to the underlying token should use sushiswap.","poolAmountOut":"Amount of index pool tokens to mint.","tokenIn":"Token to buy the underlying tokens with."},"returns":{"_0":"Amount of `tokenIn` spent."}},"swapTokensForTokensAndMintExact(uint256,bytes32[],address,uint256)":{"details":"Swaps a token for each other token in `path` through Uniswap, then mints at least `poolAmountOut` pool tokens from `indexPool`.","params":{"amountInMax":"Maximum amount of the first token in `path` to give.","indexPool":"Address of the index pool to mint tokens from.","path":"Array of encoded tokens to swap using the Narwhal router.","poolAmountOut":"Amount of pool tokens that must be received to not revert."}}},"version":1},"userdoc":{"kind":"user","methods":{},"version":1}},"settings":{"compilationTarget":{"src/contracts/IndexedNarwhalRouter.sol":"IndexedNarwhalRouter"},"evmVersion":"byzantium","libraries":{},"metadata":{"bytecodeHash":"none","useLiteralContent":true},"optimizer":{"enabled":true,"runs":800},"remappings":[]},"sources":{"src/contracts/BMath.sol":{"content":"// SPDX-License-Identifier: GPL-3.0
pragma solidity >=0.6.0;

import "./BNum.sol";

contract BMath is BNum {
  function calcSingleInGivenPoolOut(
    uint256 tokenBalanceIn,
    uint256 tokenWeightIn,
    uint256 poolSupply,
    uint256 totalWeight,
    uint256 poolAmountOut,
    uint256 swapFee
  ) internal pure returns (uint256 tokenAmountIn) {
    uint256 normalizedWeight = bdiv(tokenWeightIn, totalWeight);
    uint256 newPoolSupply = badd(poolSupply, poolAmountOut);
    uint256 poolRatio = bdiv(newPoolSupply, poolSupply);

    //uint newBalTi = poolRatio^(1/weightTi) * balTi;
    uint256 boo = bdiv(BONE, normalizedWeight);
    uint256 tokenInRatio = bpow(poolRatio, boo);
    uint256 newTokenBalanceIn = bmul(tokenInRatio, tokenBalanceIn);
    uint256 tokenAmountInAfterFee = bsub(newTokenBalanceIn, tokenBalanceIn);
    // Do reverse order of fees charged in joinswap_ExternAmountIn, this way
    //     ``` pAo == joinswap_ExternAmountIn(Ti, joinswap_PoolAmountOut(pAo, Ti)) ```
    //uint tAi = tAiAfterFee / (1 - (1-weightTi) * swapFee) ;
    uint256 zar = bmul(bsub(BONE, normalizedWeight), swapFee);
    tokenAmountIn = bdiv(tokenAmountInAfterFee, bsub(BONE, zar));
    return tokenAmountIn;
  }
}
